import numpy as np
from math import exp, sqrt

def mc_call(S0, K, r, sigma, T, n, seed, antithetic=False):
    """Price and standard error of a call from n draws of z."""
    rng = np.random.default_rng(seed)
    z = rng.standard_normal(n)
    def payoff(zz):
        ST = S0 * np.exp((r - sigma ** 2 / 2) * T + sigma * sqrt(T) * zz)
        return np.maximum(ST - K, 0)
    x = payoff(z)
    if antithetic:
        x = (x + payoff(-z)) / 2
    x = exp(-r * T) * x
    return float(np.mean(x)), float(np.std(x, ddof=1) / sqrt(n))
